// Cyrus MOD PLANNER (live-test fix, item F): the LANES a mod request can need, and the planner's output contract.
// Pure + client-safe. The planner (a cheap Haiku call on the build service, services/modbuilder/planner.js, with the
// deterministic rules in ./rules.ts as the fallback) says which lanes the PROMPT implies; the deterministic capability
// router (./decide.ts) stays the authority on what can be built (game/version, plan, flags) and says why not.
import { z } from "zod";

export const LANES = [
  "texture", "itemStates", "sound", "model3d", "creature",
  "designItem", "designMenu", "designQuest", "designBoss", "designHud", "motion",
  "config", "datapack", "worldgen", "library",
] as const;
export type Lane = (typeof LANES)[number];
export const isLane = (v: unknown): v is Lane => typeof v === "string" && (LANES as readonly string[]).includes(v);

/** Customer wording per lane (what it creates). */
export const LANE_META: Record<Lane, { label: string; creates: string }> = {
  texture: { label: "Custom textures", creates: "item and block looks drawn for this mod" },
  itemStates: { label: "Item looks per state", creates: "a different look while pulling, aiming, charging or in a mode" },
  sound: { label: "Custom sounds", creates: "new sound effects or music with subtitles" },
  model3d: { label: "3D models", creates: "shaped 3D looks beyond a flat item" },
  creature: { label: "Animated creature models", creates: "an animated custom mob model and skin" },
  designItem: { label: "Item with abilities", creates: "a typed item design: triggers, cooldowns, effects" },
  designMenu: { label: "Menus", creates: "chest-menu GUIs, shops and dialogues" },
  designQuest: { label: "Quests", creates: "objectives, chains, daily tasks and rewards" },
  designBoss: { label: "Boss fight", creates: "phases, telegraphed attacks, waves, a boss bar" },
  designHud: { label: "HUD", creates: "glyph bars and icons in the action bar, boss bar or sidebar" },
  motion: { label: "Animated props", creates: "doors, hatches, turrets and moving display-entity props" },
  config: { label: "Settings", creates: "editable tunables (damage, cooldowns, messages) in config.yml" },
  datapack: { label: "Data pack", creates: "recipes, loot tables, advancements, tags" },
  worldgen: { label: "World generation", creates: "biomes, structures, a dimension" },
  library: { label: "Library assets", creates: "ready-made sounds or textures from the Nxeon library" },
};

const LaneVerdict = z.object({
  need: z.boolean(),
  why: z.string().max(240).default(""),
  confidence: z.number().min(0).max(1).default(0.5),
});
/** What the planner model must answer: one verdict per lane it mentions (missing lanes = not needed). */
export const PlannerOutput = z.object({ lanes: z.record(z.string(), LaneVerdict) });
export type LaneNeed = { lane: Lane; need: boolean; why: string; confidence: number };
export type PlannerSource = "planner" | "rules";
export type Needs = { source: PlannerSource; lanes: LaneNeed[]; costUsd?: number; ms?: number; error?: string };

/** Parse + validate the planner model's text (it may wrap the JSON in a code fence). Null = invalid: use the rules. */
export function parsePlannerText(raw: unknown): LaneNeed[] | null {
  if (typeof raw !== "string" || !raw.trim()) return null;
  const s = raw.trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");
  const a = s.indexOf("{"), b = s.lastIndexOf("}");
  if (a < 0 || b <= a) return null;
  let json: unknown;
  try { json = JSON.parse(s.slice(a, b + 1)); } catch { return null; }
  const p = PlannerOutput.safeParse(json);
  if (!p.success) return null;
  const out: LaneNeed[] = [];
  for (const lane of LANES) {
    const v = p.data.lanes[lane];
    out.push(v ? { lane, need: v.need, why: v.why.slice(0, 200), confidence: Math.round(v.confidence * 100) / 100 } : { lane, need: false, why: "", confidence: 0.5 });
  }
  return out;
}
// Cyrus mod planner: cost and time per model for a PLANNED build (pure, client-safe). The base is lib/cyrus/estimate.ts
// (measured builds); every lane the plan BUILDS adds its share (asset specs, designs and data packs are extra files the
// model writes and checks). Blocked lanes are never counted: the estimate is for what will really be built.
import { CHANGE_COST_FACTOR, estimate, type Complexity } from "../estimate";
import { CYRUS_MODEL_IDS, cyrusModel, type CyrusModelId } from "../models";
import type { Lane } from "./lanes";

/** Extra share of a plain build's cost per built lane (time grows at 60% of that). Rough, from the R1-R5 flights. */
export const LANE_WEIGHT: Readonly<Partial<Record<Lane, number>>> = {
  texture: 0.25, itemStates: 0.1, sound: 0.2, model3d: 0.15, creature: 0.45, designItem: 0.15, designMenu: 0.15,
  designQuest: 0.2, designBoss: 0.25, designHud: 0.1, motion: 0.15, config: 0.05, datapack: 0.15, worldgen: 0.35, library: 0,
};

/**
 * MEASURED whole-build cost at Saka (costFactor 1) INCLUDING repairs, per lane group, succeeded builds only.
 * texture: eval first1 + second1 pooled (27 builds; the reliability change barely moved texture cost: the asset repairs it
 *   removed were $0.06-0.17 each and rarer than the pre-check API repairs that remain).
 * sound: eval second1 only (6 builds, image 0.13): first1's 7 builds (p50 0.57) were dominated by the "never plays" repair
 *   turns the reliability change removed, so they no longer describe a sound build.
 * designer: first1 (20 builds); second1 downgrades most of them to plain plugins, so it is kept until the strict-design
 *   journal (MB_DESIGN_STRICT auto) has rows.
 * The usual range is 0.7 x p50 .. p80 (never below the lane-weighted estimate); "up to" is p90 or 1.25 x the high end.
 * Re-measure: scripts/cyrus/eval-journal-stats.ts on the third1 journal (image 0.15) when its asset rows have finished.
 */
export const MEASURED_SAKA = {
  texture: { n: 27, p50: 0.46, p80: 0.685, p90: 0.735 },
  sound: { n: 6, p50: 0.39, p80: 0.52, p90: 0.61 },
  designer: { n: 20, p50: 0.36, p80: 0.58, p90: 0.65 },
} as const;
type MeasuredGroup = keyof typeof MEASURED_SAKA;
const GROUP_OF: Readonly<Partial<Record<Lane, MeasuredGroup>>> = {
  texture: "texture", itemStates: "texture", model3d: "texture", sound: "sound",
  designItem: "designer", designMenu: "designer", designQuest: "designer", designBoss: "designer", designHud: "designer", motion: "designer",
};

export type ModelEstimate = { model: CyrusModelId; complexity: Complexity; usd: [number, number]; /** "up to $x if it needs fixes" (a retried build costs about twice a clean one) */ upTo: number; minutes: [number, number] };

const r2 = (n: number) => Math.max(0.01, Math.round(n * 100) / 100);

export function planEstimate(text: string, model: CyrusModelId, lanes: readonly Lane[], opts: { change?: boolean } = {}): ModelEstimate {
  const e = estimate(text, model, opts);
  const w = lanes.reduce((a, l) => a + (LANE_WEIGHT[l] ?? 0), 0);
  const k = 1 + w;
  const t = 1 + w * 0.6;
  const minutes: [number, number] = [Math.max(1, Math.round(e.minutes[0] * t)), Math.max(2, Math.round(e.minutes[1] * t))];
  if (minutes[1] <= minutes[0]) minutes[1] = minutes[0] + 1;
  let lo = e.usd[0] * k, hi = e.usd[1] * k, p90 = 0;
  // the heaviest measured lane group present sets a floor (measured at Saka; scaled by the model's cost factor, changes by theirs)
  // measured at Saka only: Katara scales down by its cost factor; Yakko keeps its factor-based figure (already above these floors)
  const cf = Math.min(1, cyrusModel(model).costFactor) * (opts.change ? CHANGE_COST_FACTOR : 1);
  for (const l of lanes) {
    const g = GROUP_OF[l];
    if (!g) continue;
    const m = MEASURED_SAKA[g];
    lo = Math.max(lo, 0.7 * m.p50 * cf); hi = Math.max(hi, m.p80 * cf); p90 = Math.max(p90, m.p90 * cf);
  }
  if (hi <= lo) hi = lo * 1.3;
  const upTo = Math.max(hi * 1.25, p90);
  return { model, complexity: e.complexity, usd: [r2(lo), r2(hi)], upTo: r2(upTo), minutes };
}

export const planEstimates = (text: string, lanes: readonly Lane[], opts: { change?: boolean } = {}): ModelEstimate[] =>
  CYRUS_MODEL_IDS.map((m) => planEstimate(text, m, lanes, opts));

/**
 * The DEFAULT ("Auto") model: the cheapest model that is capable of the request. Katara only for trivial plain code
 * (the 2026-10-07 eval: the small model took 2x the turns on anything with structure), Saka for most mods (any asset or
 * designer lane), Yakko only for complex requests. Capped to what the plan unlocks (best allowed below the pick).
 */
export function autoModel(text: string, lanes: readonly Lane[], allowed: readonly CyrusModelId[] = CYRUS_MODEL_IDS): CyrusModelId {
  const e = estimate(text, "saka");
  const structured = lanes.some((l) => l !== "config");
  const pick: CyrusModelId = e.complexity === "complex" ? "yakko" : e.complexity === "simple" && !structured && e.score < 1.5 ? "katara" : "saka";
  const order: CyrusModelId[] = ["katara", "saka", "yakko"];
  if (allowed.includes(pick)) return pick;
  const below = order.slice(0, order.indexOf(pick) + 1).reverse().find((m) => allowed.includes(m));
  return below ?? allowed[0] ?? "katara";
}
// Cyrus mod planner: the DETERMINISTIC needs analysis (zero cost, no network). It is the fallback when the planner
// model is unavailable, slow or answers invalid JSON, and the floor under it: a lane a literal phrase asks for
// ("custom texture", "boss fight") is never dropped. It reuses every existing route matcher (adapter route rules,
// designer / data pack / item state words) and adds what the live test showed was missing: what a mod implies
// without saying the words (a golem that "grunts" needs sounds; a creature that "throws rocks" needs a rock item
// texture; "make it look cool" needs textures). Plain-code requests (commands, rules, chat) get no asset lanes.
import { detectAssetKinds } from "../assets/plan";
import { creatureLike } from "../assets/auto";
import { matchBossWords, matchDesignerWords, matchGameplayWords, matchHudWords, matchMotionWords, ITEM_WORDS } from "../designer/route";
import { matchDataPackRules, WORLDGEN_RULE } from "../datapack/route";
import { matchStateWords } from "../itemmodel/route";
import { LANES, type Lane, type LaneNeed } from "./lanes";

/** Sounds the request implies (a voice, an effect, music), even without the word "sound". */
export const SOUND_WORDS = /\b(sounds?|sfx|music|songs?|soundtracks?|jingles?|chimes?|bells?|grunt(?:s|ing)?|groan(?:s|ing)?|roar(?:s|ing)?|growl(?:s|ing)?|scream(?:s|ing)?|shriek(?:s|ing)?|hiss(?:es|ing)?|howl(?:s|ing)?|bark(?:s|ing)?|moan(?:s|ing)?|voice(?:s
const NO_SOUND = /\b(no|without|silent|mute[sd]?) (?:custom )?(?:sounds?|audio|music)\b/i;
/** Looks the request implies: a named custom item, glowing / legendary gear, a skin, "look cool". */
const LOOK_WORDS = /\b(textures?|retextur\w*|skins?|icons?|looks? (?:cool|awesome|epic|unique|different|like)|glow(?:s|ing)?|shiny|sparkl\w*|custom (?:items?|weapons?|armou?r|tools?|blocks?|looks?)|new (?:items?|weapons?|armou?r|tools?)|legendary|art ?style|pi
/** Material / element adjectives: a look only when they describe an item ("a ruby sword", "a frost staff"). */
const ITEM_ADJ = /\b(custom|new|special|magic(?:al)?|legendary|named|mythic|ancient|cursed|purple|golden|crystal|ruby|emerald|sapphire|amethyst|obsidian|flaming|fiery|frost|ice|lightning|thunder|shadow|void|blood)\b/i;
/** Things a creature or item throws / drops that deserve their own item look. */
const THROWN = /\b(th?r?ows?|throwing|hurls?|hurling|launch(?:es)?|shoots?|tosses?|drops?|spits?)\b[^.]{0,30}\b(rocks?|boulders?|stones?|spears?|bombs?|orbs?|fireballs?|balls?|crystals?|shards?|gems?|daggers?|knives|bones?|items?)\b/i;
/** A NEW creature (not "zombie kills give coins"). */
const NEW_CREATURE = /\b(creatures?|golems?|\d+ blocks? tall|giant (?:mob|creature|monster|golem|spider|beast)|custom (?:mobs?|creatures?|monsters?|pets?|npcs?)|new (?:mobs?|creatures?|monsters?|pets?)|summon(?:s|able)? (?:a|an|my)? ?(?:pet|creature|minion|gol
/** Moving props beyond the designer route's words (spinning, orbiting, swaying displays). */
const MOTION_EXTRA = /\b(spinning|spins|rotat(?:es|ing)|orbit(?:s|ing)?|sways?|swaying|bobs?|bobbing|waving|floating (?:display|crystal|prop|item)s?)\b/i;
/** On-screen things a server cannot draw freely (still a HUD lane: the router says what is possible). */
const SCREEN_WORDS = /\b(mini-?maps?|on[- ]screen (?:display|widget|overlay)s?|hud)\b/i;
const MODEL_WORDS = /\b(3d|three[- ]d|3-d)\b|\b(statues?|sculptures?|furniture|custom (?:entity|mob|creature|block) models?|display entit(?:y|ies))\b/i;
const TUNABLE_WORDS = /\b(config(?:urable)?|settings?|adjust(?:able)?|customi[sz]able|cooldowns?|damage|amounts?|every \d+|rates?|chances?|percent|%|\d+ (?:seconds?|minutes?|blocks?|hearts?|coins?)|radius|range|duration|limits?|prices?|rewards?)\b/i;

const need = (lane: Lane, yes: boolean, why: string, confidence = 0.7): LaneNeed => ({ lane, need: yes, why: yes ? why : "", confidence: yes ? confidence : 0.6 });

/** The deterministic needs for a request (no AI). Order = LANES. */
export function ruleNeeds(text: string, game = "minecraft"): LaneNeed[] {
  const t = (text ?? "").trim();
  const literal = new Set(detectAssetKinds(t, game));
  const creature = NEW_CREATURE.test(t) || (literal.has("creature")) || (creatureLike(t) && /\b(tall|giant|huge|spawn|summon|throws?|attacks?|follows?|pet)\b/i.test(t));
  const item = matchDesignerWords(t);
  const gp = matchGameplayWords(t);
  const boss = matchBossWords(t);
  const hud = matchHudWords(t);
  const motion = matchMotionWords(t);
  const dp = matchDataPackRules(t, game, { worldgen: true });
  const sound = !NO_SOUND.test(t) && (literal.has("sound") || SOUND_WORDS.test(t));
  const thrown = THROWN.exec(t);
  const namedItem = ITEM_WORDS.test(t) && (item.length > 0 || LOOK_WORDS.test(t) || ITEM_ADJ.test(t));
  const texture = literal.has("texture") || LOOK_WORDS.test(t) || namedItem || (!!thrown && creature);
  const states = texture && matchStateWords(t).length > 0;
  const by: Record<Lane, LaneNeed> = {
    texture: need("texture", texture, literal.has("texture") ? "the request asks for custom textures" : thrown && creature ? `the ${thrown[2].toLowerCase()} it ${thrown[1].toLowerCase()} can have its own look` : namedItem ? "a custom item gets its own look" : 
    itemStates: need("itemStates", states, "the item can look different per state (pulling, aiming, charging)", 0.6),
    sound: need("sound", sound, literal.has("sound") ? "the request asks for custom sounds" : `the request describes sounds (${(SOUND_WORDS.exec(t)?.[0] ?? "sound").toLowerCase()})`, literal.has("sound") ? 0.95 : 0.7),
    model3d: need("model3d", MODEL_WORDS.test(t), "the request describes a 3D shape", 0.6),
    creature: need("creature", creature, "the request describes a new creature with its own look", 0.75),
    designItem: need("designItem", item.length > 0, "an item with abilities (trigger, cooldown, effect)", 0.75),
    designMenu: need("designMenu", gp.menus, "the request describes a menu, shop or dialogue", 0.8),
    designQuest: need("designQuest", gp.quests, "the request describes quests or missions", 0.8),
    designBoss: need("designBoss", boss.length > 0, "the request describes a boss fight or waves", 0.8),
    designHud: need("designHud", hud.hud || hud.excluded || SCREEN_WORDS.test(t), hud.hud ? "the request describes a HUD bar or icons" : "the request asks for something drawn on screen", 0.75),
    motion: need("motion", motion.length > 0 || MOTION_EXTRA.test(t), "the request describes moving props", 0.7),
    config: need("config", TUNABLE_WORDS.test(t), "it has numbers an owner will want to tune", 0.6),
    datapack: need("datapack", dp.some((r) => r !== WORLDGEN_RULE), "recipes, loot, advancements or tags", 0.8),
    worldgen: need("worldgen", dp.includes(WORLDGEN_RULE), "biomes, structures or a dimension", 0.85),
    library: need("library", sound && /\b(music|ambien\w*|footsteps?|explosions?|bells?|chimes?|jingles?|rain|thunder)\b/i.test(t), "stock sounds fit (music, ambience, effects)", 0.5),
  };
  return LANES.map((l) => by[l]);
}

/** Lanes a literal phrase asks for: kept even when the planner model says no (never drop an explicit ask). */
export function literalLanes(text: string, game = "minecraft"): Lane[] {
  const k = detectAssetKinds(text, game);
  const out: Lane[] = [];
  if (k.includes("texture")) out.push("texture");
  if (k.includes("sound")) out.push("sound");
  if (k.includes("creature")) out.push("creature");
  if (matchBossWords(text).length) out.push("designBoss");
  const dp = matchDataPackRules(text, game, { worldgen: true });
  if (dp.includes(WORLDGEN_RULE)) out.push("worldgen");
  if (dp.some((r) => r !== WORLDGEN_RULE)) out.push("datapack");
  return out;
}

/** Merge the planner's verdicts with the literal floor (a literal ask always stays). */
export function mergeNeeds(planner: LaneNeed[] | null, text: string, game = "minecraft"): { lanes: LaneNeed[]; source: "planner" | "rules" } {
  if (!planner) return { lanes: ruleNeeds(text, game), source: "rules" };
  const floor = new Set(literalLanes(text, game));
  const rules = ruleNeeds(text, game);
  return {
    source: "planner",
    lanes: planner.map((n) => (!n.need && floor.has(n.lane) ? { ...rules.find((r) => r.lane === n.lane)!, need: true } : n)),
  };
}

};
export type ModPlan = {
  game: string;
  version: string;
  source: PlannerSource;
  lanes: PlannedLane[];
  /** Short list for the plan screen: what will be created. */
  creates: string[];
  /** Blocking-style warnings, one per blocked lane the prompt needs. */
  warnings: string[];
  /** true = the user must press "Continue anyway" before anything is held. */
  mustConfirm: boolean;
};

export type DecideInput = {
  needs: LaneNeed[];
  source: PlannerSource;
  catalogue: CapabilityCatalogue | null | undefined;
  ctx: CapabilityContext;
  /** The account's plan tier (token economy); unknown = asset creation fails closed. */
  plan: unknown;
  change?: boolean;
  /** User toggles from the plan screen: lane -> wanted. */
  toggles?: Partial<Record<Lane, boolean>>;
};

const PLAN_NAME: Record<string, string> = { saka: "Saka", all: "All models", katara: "Katara" };

export function decidePlan(i: DecideInput): ModPlan {
  const lanes: PlannedLane[] = LANES.map((lane) => {
    const n = i.needs.find((x) => x.lane === lane) ?? { lane, need: false, why: "", confidence: 0.5 };
    const t = i.toggles?.[lane];
    const wanted = t === undefined ? n.need : t;
    const capability = resolveLane(i.catalogue, lane, i.ctx);
    const meta = LANE_META[lane];
    const base = { ...n, need: wanted, label: meta.label, creates: meta.creates, capability, ...(t !== undefined && t !== n.need ? { toggled: true } : {}) };
    if (!wanted) return { ...base, state: "skip" as const, warning: null, blockedBy: null };
    if (capability.availability === "unavailable") {
      const by = capability.cause === "ok" ? "game" : capability.cause;
      return { ...base, state: "blocked" as const, blockedBy: by, warning: laneWarning(capability, meta.label, i.ctx) };
    }
    const kind = LANE_GATE[lane];
    if (kind) {
      const g = canAsset(i.plan, kind, i.change ? "edit" : "create");
      if (!g.ok) {
        const sub = capability.substitute ? ` Cyrus will build ${capability.substitute} instead.` : "";
        return { ...base, state: "blocked" as const, blockedBy: "plan" as const, ...(g.needs ? { needsPlan: g.needs } : {}), warning: `${meta.label}: ${g.reason.replace(/\.$/, "")}.${sub}${g.needs ? ` Unlock the ${PLAN_N
      }
    }
    return { ...base, state: "build" as const, warning: capability.availability === "limited" ? `${meta.label} are limited on ${i.ctx.gameName} ${i.ctx.version}: ${capability.reason}.` : null, blockedBy: null };
  });
  const warnings = lanes.filter((l) => l.state === "blocked" && l.warning).map((l) => l.warning!);
  return {
    game: i.ctx.game, version: i.ctx.version, source: i.source, lanes,
    creates: lanes.filter((l) => l.state === "build").map((l) => `${l.label}${l.why ? `: ${l.why}` : ""}`),
    warnings,
    mustConfirm: warnings.length > 0,
  };
}

export const builtLanes = (p: Pick<ModPlan, "lanes">): Lane[] => p.lanes.filter((l) => l.state === "build").map((l) => l.lane);

/**
 * The approved plan as the build's explicit `assets` request (lib/cyrus/assets/request.ts reads it). `plan: 1` marks a
 * PLANNED request: the server uses exactly these lanes instead of keyword matching (and still re-checks plan, version
 * and switches). Only lanes in state "build" are requested: a blocked lane never reaches the build.
 */
export type PlannedAssetsRequest = {
  plan: 1;
  lanes: Lane[];
  texture: boolean; sound: boolean; creature: boolean; itemmodel: boolean; datapack: boolean; worldgen: boolean; design: boolean; library: boolean;
  parts: { item: boolean; menus: boolean; quests: boolean; bosses: boolean; hud: boolean; motion: boolean };
  /** One short line per lane for the build service ("produce these"). */
  why: Partial<Record<Lane, string>>;
};
export function toAssetsRequest(p: Pick<ModPlan, "lanes">): PlannedAssetsRequest {
  const on = new Set(builtLanes(p));
  const parts = { item: on.has("designItem"), menus: on.has("designMenu"), quests: on.has("designQuest"), bosses: on.has("designBoss"), hud: on.has("designHud"), motion: on.has("motion") };
  return {
    plan: 1, lanes: LANES.filter((l) => on.has(l)),
    texture: on.has("texture") || on.has("itemStates") || on.has("model3d"), sound: on.has("sound") || on.has("library"), creature: on.has("creature"),
    itemmodel: on.has("itemStates"), datapack: on.has("datapack") || on.has("worldgen"), worldgen: on.has("worldgen"), library: on.has("library"),
    design: Object.values(parts).some(Boolean), parts,
    why: Object.fromEntries(p.lanes.filter((l) => l.state === "build" && l.why).map((l) => [l.lane, l.why.slice(0, 160)])),
  };
}

/** Read a planned request back (server side). Null = not a planned request (keyword routing as before). */
export function readPlannedRequest(raw: unknown): PlannedAssetsRequest | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw) || (raw as { plan?: unknown }).plan !== 1) return null;
  const r = raw as Record<string, unknown>;
  const lanes = (Array.isArray(r.lanes) ? r.lanes : []).filter((l): l is Lane => (LANES as readonly string[]).includes(l as string));
  const on = new Set(lanes);
  const parts = { item: on.has("designItem"), menus: on.has("designMenu"), quests: on.has("designQuest"), bosses: on.has("designBoss"), hud: on.has("designHud"), motion: on.has("motion") };
  const why: Partial<Record<Lane, string>> = {};
  if (r.why && typeof r.why === "object") for (const [k, v] of Object.entries(r.why as Record<string, unknown>)) if (on.has(k as Lane) && typeof v === "string") why[k as Lane] = v.replace(/[<>]/g, "").slice(0, 160);
  // Rebuilt from the lane list only: the booleans a client sends are never trusted on their own.
  return { ...toAssetsRequest({ lanes: lanes.map((lane) => ({ lane, state: "build" } as PlannedLane)) }), parts, why };
}
// Cyrus mod planner: the SERVER flow (dependencies injectable, so the whole path is tested with fakes and no model call).
//   1. needs:  the planner model on the build service (POST /plan, ~$0.001, 9 s budget) validated with zod; on any
//              failure, timeout or invalid answer: the deterministic rules (lib/cyrus/planner/rules.ts). A literal ask
//              ("custom texture") is never dropped.
//   2. decide: the capability router over the game's catalogue + plan tier + host switches (./decide.ts).
//   3. price:  cost / time / tokens per model for the lanes that will really be built (./estimate.ts + the economy).
import { createHash } from "node:crypto";
import { getAdapter } from "../adapters";
import type { CapabilityCatalogue, CapabilityContext } from "../adapters/capabilities";
import { modelsFor, holdRange, tokensForCost } from "../tokens/economy";
import type { TokenConfig, TokenTier } from "../tokens/config";
import type { CyrusModelId } from "../models";
import { builtLanes, decidePlan, toAssetsRequest, type ModPlan, type PlannedAssetsRequest } from "./decide";
import { autoModel, planEstimates } from "./estimate";
import { parsePlannerText, type Lane, type LaneNeed, type Needs } from "./lanes";
import { mergeNeeds } from "./rules";

export type PlannerAsk = (body: { text: string; game: string; mcVersion: string }) => Promise<{ text: string | null; costUsd: number; ms: number }>;
export type PlannerDeps = {
  /** The build service planner (svcPlan). Absent = rules only. */
  ask?: PlannerAsk;
  /** Does the service have POST /plan (health features.planner)? */
  supports?: () => Promise<boolean>;
  timeoutMs?: number;
};

const CACHE = new Map<string, { at: number; needs: Needs }>();
const CACHE_MS = 10 * 60_000;
const key = (t: string, g: string, v: string) => createHash("sha256").update(`${g}\n${v}\n${t.trim().toLowerCase()}`).digest("hex");

/** What the prompt needs: the planner model when it answers in time with valid JSON, else the rules. */
export async function analyzeNeeds(input: { text: string; game: string; mcVersion: string }, deps: PlannerDeps = {}): Promise<Needs> {
  const k = key(input.text, input.game, input.mcVersion);
  const hit = CACHE.get(k);
  if (hit && Date.now() - hit.at < CACHE_MS) return hit.needs;
  let needs: Needs;
  const rules = (error?: string): Needs => ({ ...mergeNeeds(null, input.text, input.game), ...(error ? { error } : {}) });
  if (!deps.ask || !(await (deps.supports ?? (async () => true))().catch(() => false))) needs = rules("planner not available");
  else {
    const t0 = Date.now();
    try {
      const timeout = new Promise<null>((r) => setTimeout(() => r(null), deps.timeoutMs ?? 9000));
      const ans = await Promise.race([deps.ask(input), timeout]);
      const parsed = ans ? parsePlannerText(ans.text) : null;
      if (!ans) needs = rules("planner timed out");
      else if (!parsed) needs = { ...rules("planner answer was not valid"), costUsd: ans.costUsd };
      else needs = { ...mergeNeeds(parsed, input.text, input.game), costUsd: ans.costUsd, ms: ans.ms || Date.now() - t0 };
    } catch (e) {
      needs = rules(`planner failed: ${(e as Error).message.slice(0, 80)}`);
    }
  }
  if (CACHE.size > 300) CACHE.clear();
  CACHE.set(k, { at: Date.now(), needs });
  return needs;
}

/** The host switches the capability catalogue reads (server side; fail closed: unset = off). */
export function hostFlags(env: Record<string, string | undefined> = process.env): Record<string, boolean> {
  const on = (k: string) => env[k] === "1";
  return {
    CYRUS_DESIGNER: on("CYRUS_DESIGNER"), CYRUS_ITEM_STATES: on("CYRUS_ITEM_STATES"), CYRUS_CREATURES: on("CYRUS_CREATURES"),
    CYRUS_DATAPACK_STUDIO: on("CYRUS_DATAPACK_STUDIO"), CYRUS_WORLDGEN: on("CYRUS_DATAPACK_STUDIO") && on("CYRUS_WORLDGEN"),
    CYRUS_SOUND_LIBRARY_CLEARED: on("CYRUS_SOUND_LIBRARY_CLEARED"), CYRUS_CONFIG_STUDIO: on("CYRUS_CONFIG_STUDIO"),
  };
}

export function capabilityContext(game: string, version: string, flags: Record<string, boolean>): { ctx: CapabilityContext; catalogue: CapabilityCatalogue | undefined } {
  const a = getAdapter(game);
  return {
    ctx: { game, gameName: a?.name ?? game, version, hasCapability: (c) => !!a?.versions.hasCapability(version, c), flags },
    catalogue: a?.capabilities,
  };
}

export type ModelOption = { model: CyrusModelId; usd: [number, number]; /** "up to $x if it needs fixes" */ upTo: number; minutes: [number, number]; tokens: [number, number] | null; hold: number | nul
export type PlanResponse = {
  plan: ModPlan;
  /** The explicit `assets` request for the build (only lanes in state "build"). */
  assets: PlannedAssetsRequest;
  models: ModelOption[];
  /** The Auto pick (cheapest capable model the plan unlocks). */
  auto: CyrusModelId;
  planner: { source: Needs["source"]; costUsd: number; ms: number | null; error: string | null };
};

/** The full pre-build plan for the plan screen (and the server-side plan of a build that came without one). */
export async function buildModPlan(input: { text: string; game: string; mcVersion: string; tier: TokenTier | null; change?: boolean; toggles?: Partial<Record<Lane, boolean>>; cfg?: TokenConfig | null;
  deps: PlannerDeps & { flags?: Record<string, boolean> } = {}): Promise<PlanResponse> {
  const needs: Needs = input.needs ? { source: input.source ?? "rules", lanes: input.needs, ...(input.meta ?? {}) } : await analyzeNeeds({ text: input.text, game: input.game, mcVersion: input.mcVersio
  const { ctx, catalogue } = capabilityContext(input.game, input.mcVersion, deps.flags ?? hostFlags());
  const plan = decidePlan({ needs: needs.lanes, source: needs.source, catalogue, ctx, plan: input.tier, change: input.change, toggles: input.toggles });
  const lanes = builtLanes(plan);
  const allowed = input.tier ? modelsFor(input.tier) : (["katara", "saka", "yakko"] as CyrusModelId[]);
  const cfg = input.cfg ?? null;
  const models: ModelOption[] = planEstimates(input.text, lanes, { change: input.change }).map((e) => {
    const tokens: [number, number] | null = cfg ? [tokensForCost(e.usd[0], e.model, cfg), tokensForCost(e.usd[1], e.model, cfg)] : null;
    return { model: e.model, usd: e.usd, upTo: e.upTo, minutes: e.minutes, tokens, hold: cfg ? holdRange(e.model, e.complexity, cfg, e.usd)[1] : null, allowed: allowed.includes(e.model) };
  });
  return {
    plan, assets: toAssetsRequest(plan), models, auto: autoModel(input.text, lanes, allowed),
    planner: { source: needs.source, costUsd: needs.costUsd ?? 0, ms: needs.ms ?? null, error: needs.error ?? null },
  };
}
