// Cyrus: pre-build estimate (client-safe, pure, unit-tested).
//
// Complexity comes from a feature count over the request text (the same idea
// as the build service's router, kept deliberately small here: it only drives
// the hint and the estimate, never what the service actually does).
// Time and cost ranges are anchored on the Phase 0 measurement (2026-10-06,
// 10 real builds on the balanced model: 40-299 s, $0.08-$0.47 API-equivalent,
// avg 160 s / $0.28). The "complex" upper end is extrapolated. Every figure is
// shown to the customer as an estimate.
import { cyrusModel, type CyrusModelId } from "./models";

export type Complexity = "simple" | "standard" | "complex";

const FEATURES: [string, number, RegExp][] = [
  ["menus", 2, /\b(gui|menus?|chest (menu|gui)|inventory (menu|gui)|clicks?)\b/i],
  ["saved data", 1, /\b(saved?|persist\w*|stored?|survive|restarts?|to (a )?file|database)\b/i],
  ["scoreboard", 2, /\b(scoreboard|sidebar|tab ?list|leaderboard|top \d+|boss ?bar)\b/i],
  ["economy", 2, /\b(coins?|money|balance|economy|shop|buy|sell|prices?|pay)\b/i],
  ["regions", 2, /\b(regions?|zones?|claims?|arena|pos1|pos2|corners?)\b/i],
  ["protection", 1, /\b(protect\w*|grief\w*|trusted?|explosions?)\b/i],
  ["mini-game", 3, /\b(mini-?game|rounds?|winner|teams?|lobby|countdown)\b/i],
  ["boss", 2, /\b(boss(?! ?bar)|phases?|minions?|waves?)\b/i],
  ["timers", 1, /\b(every \d*\s*(seconds?|minutes?|hours?)|timer|cooldown|daily|streaks?)\b/i],
  ["quests", 3, /\b(quests?|missions?|achievements?|objectives?)\b/i],
  ["effects", 1, /\b(potion|effects?|particles?|trails?|sounds?|titles?|fireworks?)\b/i],
  ["items", 1, /\b(items?|recipes?|enchant\w*|lore|loot|drops?|rewards?)\b/i],
  ["mobs", 1, /\b(spawns?|mobs?|zombies?|skeletons?|creepers?|entit(y|ies)|npcs?|creatures?|golems?|monsters?)\b/i],
  ["config", 0.5, /\b(config(urable)?|settings?)\b/i],
  ["permissions", 0.5, /\b(permissions?|operators?|ranks?)\b/i],
];

/** A change (edit / refine) costs about this share of a fresh build of the same size. */
export const CHANGE_COST_FACTOR = 0.8;

export type Estimate = {
  complexity: Complexity;
  score: number;
  features: string[];
  commands: number;
  recommended: CyrusModelId;
  minutes: [number, number];
  usd: [number, number];
};

const BASE: Record<Complexity, { min: [number, number]; usd: [number, number] }> = {
  simple: { min: [1, 2], usd: [0.08, 0.18] },
  standard: { min: [2, 4], usd: [0.15, 0.35] },
  complex: { min: [3, 6], usd: [0.3, 0.6] },
};

export function estimate(text: string, model: CyrusModelId, opts: { change?: boolean } = {}): Estimate {
  const t = text || "";
  const features: string[] = [];
  let score = 0;
  for (const [name, w, re] of FEATURES) if (re.test(t)) { features.push(name); score += w; }
  const commands = new Set((t.match(/\/[a-z][a-z0-9_-]{1,24}/gi) || []).map((c) => c.toLowerCase())).size;
  score += Math.max(0, commands - 1) * 0.5;
  score += Math.min(2, Math.floor(t.length / 450));
  const complexity: Complexity = score >= 7.5 ? "complex" : score >= 3 ? "standard" : "simple";
  const recommended: CyrusModelId = complexity === "simple" ? "katara" : complexity === "standard" ? "saka" : "yakko";

  const recommended: CyrusModelId = complexity === "simple" ? "katara" : complexity === "standard" ? "saka" : "yakko";
  const m = cyrusModel(model);
  const b = BASE[complexity];
  // A change request reads the old code first but usually writes less.
  const k = opts.change ? CHANGE_COST_FACTOR : 1;
  const usd: [number, number] = [round2(b.usd[0] * m.costFactor * k), round2(b.usd[1] * m.costFactor * k)];
  const minutes: [number, number] = [Math.max(1, Math.round(b.min[0] * m.timeFactor * k)), Math.max(1, Math.round(b.min[1] * m.timeFactor * k))];
  if (minutes[1] <= minutes[0]) minutes[1] = minutes[0] + 1;
  return { complexity, score: Math.round(score * 10) / 10, features, commands, recommended, minutes, usd };
}

function round2(n: number) { return Math.max(0.01, Math.round(n * 100) / 100); }

export function fmtUsd([a, b]: [number, number]): string {
  return `$${a.toFixed(2)}–${b.toFixed(2)}`;
}

/** Is the chosen model clearly under-powered (or wasteful) for the request? */
export function modelAdvice(e: Estimate, chosen: CyrusModelId): "ok" | "under" | "over" {
  const rank = { katara: 0, saka: 1, yakko: 2 } as const;
  const d = rank[chosen] - rank[e.recommended];
  return d < 0 ? "under" : d > 0 && e.complexity === "simple" ? "over" : "ok";
}
