export const MOD_SUITES_FLAG = "CYRUS_MOD_SUITES";
export const modSuitesOn = (env: Record<string, string | undefined> = process.env) => env[MOD_SUITES_FLAG] === "1";
export const SPEC_V2 = 2 as const;

export const MODULE_KINDS = ["items", "creatures", "quests", "menus", "bosses", "hud", "textures", "sounds", "models", "motions", "config", "datapack", "worldgen", "code"] as const;
export type ModuleKind = (typeof MODULE_KINDS)[number];
/** What a module can provide to others: `<kind>:<id>` (the id lives in the project's one namespace). */
export const PROVIDE_KINDS = ["item", "entity", "quest", "menu", "boss", "encounter", "hud", "motion", "sound", "texture", "model", "recipe", "loot", "advancement", "function", "config"] as const;
export const PROVIDE_RE = new RegExp(`^(${PROVIDE_KINDS.join("|")}):[a-z][a-z0-9_]{0,47}$`);
/** Suite caps (flag on). Runtime caps of the designers (live bosses, tasks, per-activation budgets) do NOT grow. */
export const SUITE_LIMITS = { maxModules: 32, maxDesignsPerModule: 40, maxProvides: 64, maxDepends: 16 } as const;
/** Module file ownership: prefixes of project paths the module owns (custom code, extra resources). */
const PATH_PREFIX_RE = /^[a-zA-Z0-9_.-]+(\/[a-zA-Z0-9_.-]+)*\/?$/;

export const ModuleZ = z.object({
  id: z.string().regex(SLOT_ID_RE, "module ids are lowercase letters, digits and underscores"),
  kind: z.enum(MODULE_KINDS),
  title: z.string().trim().min(1).max(80),
  summary: z.string().trim().max(500).optional(),
  /** Takes every design and asset slot no other module lists (a migrated v1 spec has one such module). */
  default: z.boolean().optional(),
  dependsOn: z.array(z.string().regex(SLOT_ID_RE)).max(SUITE_LIMITS.maxDepends).default([]),
  requirementIds: z.array(z.string().regex(REQ_ID_RE)).max(100).default([]),
  /** Asset slot ids (ModSpec assets[].id) of this module. */
  assets: z.array(z.string().regex(SLOT_ID_RE)).max(200).default([]),
  /** Design ids (assets/designs/<id>.json) of this module. */
  designs: z.array(z.string().regex(/^[a-z][a-z0-9_]{1,31}$/)).max(SUITE_LIMITS.maxDesignsPerModule).default([]),
  files: z.array(z.string().max(200).regex(PATH_PREFIX_RE)).max(20).default([]),
  provides: z.array(z.string().regex(PROVIDE_RE, "provides are <kind>:<id>, e.g. item:frost_blade")).max(SUITE_LIMITS.maxProvides).default([]),
  uses: z.array(z.string().regex(PROVIDE_RE)).max(SUITE_LIMITS.maxProvides).default([]),
}).strict();
export type ModSpecModule = z.output<typeof ModuleZ>;

export const ModSpecV2Schema = ModSpecV1Schema.extend({
  schemaVersion: z.literal(2),
  modules: z.array(ModuleZ).min(1).max(SUITE_LIMITS.maxModules),
}).strict();
export type ModSpecV2 = z.output<typeof ModSpecV2Schema>;

// ------------------------------------------------------------------------------------------------ migration v1 -> v2
/** The module kind a v1 spec most looks like (one module). */
function mainKind(doc: Record<string, unknown>): ModuleKind {
  const routes = Array.isArray(doc.routes) ? doc.routes : [];
  const kinds = new Set((Array.isArray(doc.assets) ? doc.assets : []).map((a) => (a as { kind?: string })?.kind));
  if (routes.length === 1 && routes[0] === "dataPack") return "datapack";
  if (routes.includes("plugin")) return "code";
  if (kinds.size === 1 && kinds.has("texture")) return "textures";
  if (kinds.size === 1 && kinds.has("sound")) return "sounds";
  return "code";
}
