def facts_block(v):
    """Batch 2 (BF catalogue, item 5 + section c): only what javap found in THIS version's jar (api-facts.verified.json)."""
    F = json.load(open(os.path.join(HERE, "api-facts.json")))
    R = json.load(open(os.path.join(HERE, "api-facts.verified.json")))
    assert R["factsVersion"] == F["version"], "api-facts.verified.json is stale: re-run verify-api-facts.py on node-2"
    byid = {f["id"]: f for f in F["facts"]}

    def ok(fid, ver):
        r = R["facts"][fid][ver]
        if not r["present"] or not all(m["present"] for m in r["members"].values()):
            return False
        return all(ok(q, ver) for q in byid[fid].get("requires", []))

    def text(f):
        r = R["facts"][f["id"]][v]
        t = f["say"]
        if r.get("kind") == "class" and f["class"].split(".")[-1].endswith("Event"):
            others = [w for w in R["versions"] if w != v and R["facts"][f["id"]][w].get("cancellable")]
            if not r["cancellable"] and others:
                t += f" [NOT cancellable on {v}; it is from {others[0]}]"
        if f["group"] in ("blocks2", "players2", "entities2") and r.get("kind") == "class" and not r.get("cancellable") and "ancel" not in t:
            t += " [not cancellable]"
        fl = f.get("flown")
        if fl and v in fl["versions"]:
            t += "; " + fl["text"]
        dep = [m for m, mm in r["members"].items() if mm["deprecated"]]
        if r.get("kind") == "class" and r.get("deprecated"):
            t += " (class deprecated here)"
        if dep:
            t += " (deprecated here: " + ", ".join(dep) + ")"
        return t

    L = ["## More events and methods real plugins use (each one javap-checked against this version's jar)"]
    for g, title in GROUPS:
        items = [text(f) for f in F["facts"] if f["group"] == g and f.get("say") and ok(f["id"], v)]
        if items:
            L.append(f"- {title}: " + "; ".join(items) + ".")
    if ok("Dialog", v):
        L.append("- Dialog API details: " + byid["Dialog"]["say"] + ".")
    moved = []
    if ok("EntityKnockbackByEntityEvent.paper", v):
        dep = R["facts"]["EntityKnockbackByEntityEvent.bukkit"][v]
        moved.append("knockback by a hit: import com.destroystokyo.paper.event.entity.EntityKnockbackByEntityEvent (getHitBy())" +
                     ("; the org.bukkit.event.entity class of the same name is deprecated here" if dep["present"] and dep["deprecated"] else "") +
                     ("; io.papermc.paper.event.entity.EntityKnockbackEvent covers every knockback" if ok("EntityKnockbackEvent.paper", v) else ""))
    if ok("PlayerCustomClickEvent.paper", v):
        moved.append("PlayerCustomClickEvent is io.papermc.paper.event.player.PlayerCustomClickEvent (there is no org.bukkit.event.player one)")
    if moved:
        L.append("- Package traps: " + "; ".join(moved) + ".")
    absent = []
    for f in F["facts"]:
        if not (f.get("say") or f.get("absentName")) or f["group"] == "moved" or ok(f["id"], v):
            continue
        first = next((w for w in R["versions"] if ok(f["id"], w)), None)
        if first:
            absent.append(f"{f.get('absentName') or f['class'].split('.')[-1]} ({first}+)")
    if absent:
        L.append(f"- NOT in {v} (compile error here; only on newer supported versions): " + ", ".join(absent) + ".")
    pf = R.get("packFormats", {}).get(v)
    if pf:
        fmt = lambda x: f"{x[0]}.{x[1]}" if x[1] else f"{x[0]}"
        L.append(f"- Pack formats for {v} (this version's vanilla jar): resource pack {fmt(pf['resource'])}, data pack {fmt(pf['data'])}.")
    return "\n".join(L) + "\n"


os.makedirs(OUT, exist_ok=True)
for v in VERS:
    s = sheet(v) + "\n" + facts_block(v)
    open(os.path.join(OUT, f"{v}.md"), "w").write(s)
    print(v, len(s), "chars", len(s.split()), "words")
