              ) : null}
              {current.plan.warnings.length ? <div role="alert" style={{ display: "grid", gap: 4, fontSize: 13, color: "var(--cx-warn)" }}><b>{PLAN_WARNING_COPY.heading}</b><span className="cx-muted">{PLAN_WARNING_COPY.intro}</span>{current.plan.warnings.map((w) => <span key={w}>{w}</span>)}</div> : null}
              <div className="cx-muted" style={{ fontSize: 13 }}>Cyrus will create: {current.plan.lanes.filter((l) => l.state === "build").map((l) => l.label).join(", ") || "plugin code only (no custom assets needed)"}</div>
              {bank ? (
                <div role="radiogroup" aria-label="How to build it" style={{ display: "grid", gap: 6 }} data-testid="nm-bank">
                  <button type="button" role="radio" aria-checked={useBank} className="cx-opt" onClick={() => setBankPick({ key: `${planKey}\n${bank.id}`, on: true })}>
                    <span className="cx-t">Ready-made (instant)</span>
                    <span className="cx-d">{bank.title} · {bank.tokens !== null ? `${n(bank.tokens)} tokens` : "no AI cost"} · under a minute, no AI. {bank.summary}</span>
                    {bank.mode === "offer" ? <span className="cx-d" style={{ color: "var(--cx-warn)" }}>{bank.note}</span> : null}
                  </button>
                  <button type="button" role="radio" aria-checked={!useBank} className="cx-opt" onClick={() => setBankPick({ key: `${planKey}\n${bank.id}`, on: false })}>
                    <span className="cx-t">Built by AI</span>
                    <span className="cx-d">{(() => { const m = current.models.find((x) => x.model === model); return m ? `${m.minutes[0]}–${m.minutes[1]} min${m.tokens ? ` · ${n(m.tokens[0])}–${n(m.tokens[1])} tokens` : ""}` : "estimate on the next step"; })()} · exactly what you described</span>
                  </button>
                </div>
              ) : null}
              {(() => { const m = current.models.find((x) => x.model === model); return m && !bank ? <div className="cx-row"><span className="cx-grow cx-muted">Estimate</span><span>{m.minutes[0]}–{m.minutes[1]} min{m.tokens ? ` · ${n(m.tokens[0])}–${n(m.tokens[1])} tokens` : ""}</span></div> : null; })()}
            </div>
          ) : null}
          <button type="button" className="cx-btn cx-btn-energy" disabled={busy || !prompt.trim() || !version || (!useBank && (locked || short)) || current?.buildable === false} onClick={create} data-tour="build">{busy ? (current ? "Starting…" : "Planning…") : !current ? "Plan this mod" : useBank ? "Use ready-made" : current
          {err ? <p className="cx-error" role="alert" style={{ margin: 0 }}>{err}</p> : null}
          <p className="cx-faint" style={{ margin: 0, fontSize: 12 }}>Every build passes a safety scan. When Test Flight runs, its result shows on the project page before you install.</p>
        </section>
      </aside>
    </div>
  );
}
